"""Shared fakes and fixtures. No test ever reaches a real model."""

import itertools
from collections.abc import Callable, Iterator, Sequence

import pytest
from fastapi.testclient import TestClient
from langchain_core.callbacks import CallbackManagerForLLMRun
from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
from langchain_core.messages import AIMessage, BaseMessage
from langchain_core.outputs import ChatResult
from pydantic import Field

from app.main import create_app


class ScriptedChatModel(GenericFakeChatModel):
    """A fake chat model that replays scripted messages and records its inputs."""

    received: list[list[BaseMessage]] = Field(default_factory=list)

    def bind_tools(self, tools: Sequence[object], **kwargs: object) -> "ScriptedChatModel":
        return self

    def _generate(
        self,
        messages: list[BaseMessage],
        stop: list[str] | None = None,
        run_manager: CallbackManagerForLLMRun | None = None,
        **kwargs: object,
    ) -> ChatResult:
        self.received.append(list(messages))
        return super()._generate(messages, stop=stop, run_manager=run_manager, **kwargs)

    @property
    def last_user_text(self) -> str:
        return next(message.text for message in reversed(self.received[-1]) if message.type == "human")


def tool_call(name: str, args: dict[str, str], call_id: str) -> AIMessage:
    return AIMessage(content="", tool_calls=[{"name": name, "args": args, "id": call_id}])


def endless_calculator_calls() -> Iterator[AIMessage]:
    """A model that asks for one more calculation on every step, forever."""
    for step in itertools.count():
        yield tool_call("calculator", {"expression": f"{step} + 1"}, f"call_{step}")


@pytest.fixture(autouse=True)
def clean_environment(monkeypatch: pytest.MonkeyPatch) -> None:
    for name in ("AGENT_MODEL", "BLOCKED_TOPICS", "MAX_TOOL_CALLS"):
        monkeypatch.delenv(name, raising=False)


type ClientFactory = Callable[[ScriptedChatModel], TestClient]


@pytest.fixture
def client_for() -> ClientFactory:
    def build(model: ScriptedChatModel) -> TestClient:
        return TestClient(create_app(model))

    return build


@pytest.fixture
def replying_model() -> ScriptedChatModel:
    return ScriptedChatModel(messages=iter([AIMessage(content="Happy to help.")]))

